-- Notification Authority & Asset Ownership
-- Ownership is the authoritative boundary for external notification fan-out.
-- Super admins retain global visibility; client recipients only receive events
-- generated by assets explicitly assigned to their client.

ALTER TABLE vehicles
  ADD COLUMN IF NOT EXISTS client_id UUID REFERENCES cargo_clients(id);

CREATE INDEX IF NOT EXISTS idx_vehicles_org_client
  ON vehicles (org_id, client_id)
  WHERE deleted_at IS NULL;

ALTER TABLE guardian_devices
  ADD COLUMN IF NOT EXISTS client_id UUID REFERENCES cargo_clients(id);

CREATE INDEX IF NOT EXISTS idx_guardian_devices_org_client
  ON guardian_devices (org_id, client_id)
  WHERE deleted_at IS NULL;

ALTER TABLE communication_enrollments
  ADD COLUMN IF NOT EXISTS client_id UUID REFERENCES cargo_clients(id);

ALTER TABLE communication_enrollments
  DROP CONSTRAINT IF EXISTS communication_enrollment_fleet_scope;

ALTER TABLE communication_enrollments
  ADD CONSTRAINT communication_enrollment_fleet_scope CHECK (
    (domain = 'fleet' AND cds_customer_id IS NULL)
    OR (domain = 'cds' AND cds_customer_id IS NOT NULL AND client_id IS NULL)
    OR (domain = 'platform' AND cds_customer_id IS NULL AND client_id IS NULL)
  );

CREATE INDEX IF NOT EXISTS idx_communication_enrollments_fleet_client
  ON communication_enrollments (org_id, client_id, status)
  WHERE domain = 'fleet';

COMMENT ON COLUMN vehicles.client_id IS 'Authoritative client ownership. NULL means Admin-owned/unassigned for notification routing.';
COMMENT ON COLUMN guardian_devices.client_id IS 'Authoritative client ownership when the device is not inheriting ownership from an assigned vehicle.';
COMMENT ON COLUMN communication_enrollments.client_id IS 'Fleet notification recipient scope. NULL means the enrollment is not client-scoped.';
